// Raises every Pod target's IPHONEOS_DEPLOYMENT_TARGET to the app's minimum.
//
// Xcode 27 rejects deployment targets below iOS 15 outright, and a few pods
// still declare much older ones on their resource-bundle targets
// (RNCAsyncStorage 13.4, SDWebImage 9.0), which fails the whole build.
// ios/ is generated by prebuild, so the fix lives here rather than in the Podfile.
const { withDangerousMod } = require('expo/config-plugins');
const fs = require('fs');
const path = require('path');

const MARKER = '# with-pod-deployment-target';

module.exports = function withPodDeploymentTarget(config, { minimum = '15.5' } = {}) {
  return withDangerousMod(config, [
    'ios',
    (cfg) => {
      const podfile = path.join(cfg.modRequest.platformProjectRoot, 'Podfile');
      let src = fs.readFileSync(podfile, 'utf8');
      if (!src.includes(MARKER)) {
        const snippet = `
    ${MARKER}
    installer.pods_project.targets.each do |target|
      target.build_configurations.each do |bc|
        current = bc.build_settings['IPHONEOS_DEPLOYMENT_TARGET']
        if current.nil? || Gem::Version.new(current) < Gem::Version.new('${minimum}')
          bc.build_settings['IPHONEOS_DEPLOYMENT_TARGET'] = '${minimum}'
        end
      end
    end
`;
        src = src.replace(/(post_install do \|installer\|\n)/, `$1${snippet}`);
        fs.writeFileSync(podfile, src);
      }
      return cfg;
    },
  ]);
};
